  expected_count integer;
  inserted_count integer;
  existing_count bigint;
BEGIN
  expected_count := jsonb_array_length(payload);
  IF expected_count <> 195 THEN
    RAISE EXCEPTION 'Expected 195 HSK 1 questions; found %', expected_count;
  END IF;

  SELECT count(*) INTO existing_count FROM public.grammar_questions;
  IF existing_count <> 0 THEN
    RAISE EXCEPTION 'Import stopped: grammar_questions contains % rows. This import expects an empty table to prevent duplicates.', existing_count;
  END IF;

  INSERT INTO public.grammar_questions (pattern_id, sort_order, exercise_data)
  SELECT (value->>'pattern_id')::bigint,
         (value->>'sort_order')::smallint,
         value->'exercise_data'
  FROM jsonb_array_elements(payload) AS p(value);

  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count <> expected_count THEN
    RAISE EXCEPTION 'Import stopped: expected % rows but inserted %', expected_count, inserted_count;
  END IF;
END
